const mongoose = require('mongoose');

// A warning memo generated from a checkout red flag — either issued directly
// by the Anuvadini Super Admin or auto-generated (as 'pending') when the
// configured rule triggers. Permanent history: memos are never deleted; status
// moves pending → issued → acknowledged → closed with a full trail.
const statusEventSchema = new mongoose.Schema(
  {
    status: { type: String, required: true },
    by: { type: String, default: 'Anuvadini Super Admin' },
    at: { type: Date, default: Date.now },
  },
  { _id: false }
);

const complianceMemoSchema = new mongoose.Schema(
  {
    referenceNumber: { type: String, required: true, unique: true }, // ANUVADINI/AC/<year>/<seq>
    redFlag: { type: mongoose.Schema.Types.ObjectId, ref: 'CheckoutRedFlag' },
    student: { type: mongoose.Schema.Types.ObjectId, ref: 'Student', required: true },
    organization: { type: mongoose.Schema.Types.ObjectId, ref: 'Organization' },

    // Full snapshot — a memo must remain readable forever, standalone.
    organizationName: { type: String, default: null },
    studentName: { type: String, default: null },
    uid: { type: String, default: null },
    department: { type: String, default: null },
    designation: { type: String, default: null },

    issueType: { type: String, default: 'Repeated Missing Checkout Attendance' },
    violationCount: { type: Number, default: 0 },
    violationDates: [{ type: String }],
    attendanceSummary: {
      windowDays: { type: Number, default: 30 },
      totalCheckIns: { type: Number, default: 0 },
      missedCheckouts: { type: Number, default: 0 },
      missedPct: { type: Number, default: 0 },
      riskLevel: { type: String, default: null },
    },
    warningMessage: { type: String, required: true },

    issuedBy: { type: String, default: 'Anuvadini Super Admin' },
    issuedAt: { type: Date, default: null }, // set when status becomes 'issued'
    autoGenerated: { type: Boolean, default: false },

    status: { type: String, enum: ['pending', 'issued', 'acknowledged', 'closed'], default: 'pending' },
    statusHistory: [statusEventSchema],
  },
  { timestamps: true }
);

complianceMemoSchema.index({ status: 1, createdAt: -1 });
complianceMemoSchema.index({ student: 1, createdAt: -1 });
complianceMemoSchema.index({ organization: 1, createdAt: -1 });

module.exports = mongoose.model('ComplianceMemo', complianceMemoSchema);
